shader_type sky;

uniform vec4 void_base_color : source_color = vec4(0.02, 0.01, 0.05, 1.0); // Very deep, dark purple-blue void
uniform vec4 memory_shimmer_color : source_color = vec4(0.6, 0.5, 0.8, 1.0); // Muted, ethereal purple
uniform vec4 hope_glow_color : source_color = vec4(0.9, 0.8, 0.6, 1.0); // Faint amber/gold glow for hope
uniform float fragment_density : hint_range(0.0, 0.1) = 0.025; // Sparse fragments
uniform float fragment_scale : hint_range(0.01, 0.5) = 0.1; // Size of individual fragments
uniform float drift_speed : hint_range(0.0, 0.2) = 0.02; // Slow, contemplative drift
uniform float shimmer_intensity : hint_range(0.0, 2.0) = 1.0; // Subtle shimmer
uniform float turbulence_scale : hint_range(0.1, 10.0) = 3.0; // Scale of noise for turbulence
uniform float turbulence_speed : hint_range(0.0, 1.0) = 0.05; // Speed of turbulence

float hash12(vec2 p) {
    p = fract(p * vec2(5.3983, 5.4427));
    p += dot(p.yx, p.xy + vec2(21.5351, 14.3137));
    return fract(p.x * p.y * 95.4337);
}

vec3 _process_sky() {
    vec3 dir = normalize(VEC_DIR); // Direction vector for skybox/sphere
    vec2 uv = vec2(atan(dir.z, dir.x) / (2.0 * PI) + 0.5, acos(dir.y) / PI); // Spherical UV mapping

    // Combine multiple noise layers for complex "cosmic dust" / "memory fragment" effect
    float noise_val = hash12(uv * turbulence_scale + TIME * drift_speed);
    noise_val += hash12(uv * turbulence_scale * 1.5 - TIME * drift_speed * 0.7);
    noise_val *= 0.5;

    vec3 final_color = void_base_color.rgb;

    // Create glowing fragments based on noise threshold
    if (noise_val > (1.0 - fragment_density)) {
        float fragment_intensity = smoothstep(1.0 - fragment_scale, 1.0 - fragment_scale * 0.5, noise_val);
        vec3 fragment_blend = mix(memory_shimmer_color.rgb, hope_glow_color.rgb, fragment_intensity * shimmer_intensity);
        final_color = mix(final_color, fragment_blend, fragment_intensity);
    }

    return final_color;
}

shader_type spatial;
render_mode unshaded;

uniform vec4 primary_color : source_color = vec4(0.02, 0.0, 0.03, 1.0); // Deep, dark void color
uniform vec4 weave_color : source_color = vec4(0.1, 0.05, 0.15, 0.8); // Faint, shimmering weave color
uniform float weave_density : hint_range(0.0, 10.0, 0.1) = 2.0;
uniform float weave_thickness : hint_range(0.0, 1.0, 0.01) = 0.005;
uniform float noise_speed : hint_range(0.0, 1.0, 0.01) = 0.02;
uniform float distortion_strength : hint_range(0.0, 1.0, 0.01) = 0.05;

// A simple pseudo-random function for noise
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

// A simple noise function for subtle variations
float snoise(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    fp = fp*fp*(3.0-2.0*fp);
    float bl = rand(ip);
    float br = rand(ip + vec2(1.0, 0.0));
    float tl = rand(ip + vec2(0.0, 1.0));
    float tr = rand(ip + vec2(1.0, 1.0));
    return mix(mix(bl, br, fp.x), mix(tl, tr, fp.x), fp.y);
}

void fragment() {
    vec2 uv = SCREEN_UV;
    vec2 current_uv = uv;

    // Add subtle, slow-moving noise for distortion, reflecting "shards" and "unraveling"
    vec2 noise_offset = vec2(snoise(current_uv * 5.0 + TIME * noise_speed), snoise(current_uv * 5.0 + TIME * noise_speed + 10.0));
    current_uv += noise_offset * distortion_strength;

    // Calculate a grid-like pattern for the "weave"
    vec2 grid_uv = current_uv * weave_density;
    vec2 grid_fract = fract(grid_uv);
    vec2 grid_floor = floor(grid_uv);

    float line_x = smoothstep(0.5 - weave_thickness, 0.5 + weave_thickness, grid_fract.x);
    float line_y = smoothstep(0.5 - weave_thickness, 0.5 + weave_thickness, grid_fract.y);

    float weave_pattern = 1.0 - (line_x * line_y + (1.0 - line_x) * (1.0 - line_y)); // Intersecting lines

    // Add some subtle, swirling noise to make the weave less rigid
    float swirl_noise = snoise(current_uv * 10.0 + TIME * noise_speed * 0.5);
    weave_pattern += swirl_noise * 0.1; // Faint distortion

    // Combine background color with the weave pattern
    vec4 final_color = mix(primary_color, weave_color, clamp(weave_pattern, 0.0, 1.0));

    ALBEDO = final_color.rgb;
    ALPHA = final_color.a;
}
